<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Support Contact Form</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #08111f;
      --panel: rgba(14, 22, 38, 0.92);
      --panel-border: rgba(153, 178, 255, 0.14);
      --text: #e8eefc;
      --muted: #93a4c7;
      --accent: #7c9cff;
      --accent-strong: #9bb2ff;
      --field: #0f1728;
      --field-border: #25324b;
      --error: #ff7f9f;
      --shadow: 0 22px 80px rgba(0, 0, 0, 0.45);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 32px 16px;
      font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top, rgba(124, 156, 255, 0.22), transparent 32%),
        linear-gradient(180deg, #060d18 0%, #0a1425 100%);
      color: var(--text);
    }

    .contact-shell {
      width: min(720px, 100%);
      padding: 32px;
      border: 1px solid var(--panel-border);
      border-radius: 24px;
      background: var(--panel);
      box-shadow: var(--shadow);
      backdrop-filter: blur(14px);
    }

    .eyebrow {
      margin: 0 0 10px;
      color: var(--accent-strong);
      font-size: 0.85rem;
      font-weight: 700;
      letter-spacing: 0.12em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0 0 10px;
      font-size: clamp(2rem, 4vw, 3rem);
      line-height: 1.05;
    }

    .lead {
      margin: 0 0 28px;
      max-width: 54ch;
      color: var(--muted);
      line-height: 1.6;
    }

    form {
      display: grid;
      gap: 18px;
    }

    .form-field {
      display: grid;
      gap: 8px;
    }

    label {
      font-size: 0.95rem;
      font-weight: 600;
      color: #dbe4fb;
    }

    input {
      width: 100%;
      border: 1px solid var(--field-border);
      border-radius: 14px;
      padding: 14px 16px;
      background: var(--field);
      color: var(--text);
      font: inherit;
      outline: none;
      transition: border-color 0.18s ease, box-shadow 0.18s ease, transform 0.18s ease;
    }

    input::placeholder {
      color: #6f7f9f;
    }

    input:focus {
      border-color: rgba(124, 156, 255, 0.9);
      box-shadow: 0 0 0 4px rgba(124, 156, 255, 0.18);
    }

    .helper {
      margin: 0;
      color: var(--muted);
      font-size: 0.88rem;
      line-height: 1.45;
    }

    .error {
      display: none;
      margin: 0;
      color: var(--error);
      font-size: 0.88rem;
      line-height: 1.45;
    }

    .form-field[data-invalid="true"] .error {
      display: block;
    }

    .form-field[data-invalid="true"] input {
      border-color: rgba(255, 127, 159, 0.9);
      box-shadow: 0 0 0 4px rgba(255, 127, 159, 0.12);
    }

    .submit-row {
      display: flex;
      justify-content: flex-start;
      padding-top: 6px;
    }

    button {
      border: 0;
      border-radius: 14px;
      padding: 14px 20px;
      background: linear-gradient(135deg, var(--accent), #5f7cff);
      color: white;
      font: inherit;
      font-weight: 700;
      letter-spacing: 0.01em;
      cursor: pointer;
      box-shadow: 0 16px 34px rgba(95, 124, 255, 0.28);
      transition: transform 0.18s ease, box-shadow 0.18s ease, filter 0.18s ease;
    }

    button:hover {
      transform: translateY(-1px);
      box-shadow: 0 18px 38px rgba(95, 124, 255, 0.34);
    }

    button:active {
      transform: translateY(0);
      filter: brightness(0.98);
    }

    @media (max-width: 640px) {
      .contact-shell {
        padding: 22px;
        border-radius: 20px;
      }
    }
  </style>
</head>
<body>
  <main class="contact-shell">
    <p class="eyebrow">Support</p>
    <h1>Contact our team</h1>
    <p class="lead">Send us your details and we’ll get back to you as soon as possible.</p>

    <form id="support-form" novalidate>
      <div class="form-field" data-field="fullName">
        <label for="fullName">Full name</label>
        <input id="fullName" name="fullName" type="text" autocomplete="name" required aria-describedby="fullName-error" placeholder="Alex Johnson" />
        <p class="error" id="fullName-error">Full name is required.</p>
      </div>

      <div class="form-field" data-field="email">
        <label for="email">Email address</label>
        <input id="email" name="email" type="email" autocomplete="email" required aria-describedby="email-error" placeholder="alex@company.com" />
        <p class="error" id="email-error">Please enter a valid email address.</p>
      </div>

      <div class="form-field" data-field="phone">
        <label for="phone">Phone number</label>
        <input id="phone" name="phone" type="tel" autocomplete="tel" inputmode="tel" aria-describedby="phone-help phone-error" placeholder="+1 (555) 123-4567" />
        <p class="helper" id="phone-help">Optional. Use the format +1 (555) 123-4567 or similar international format.</p>
        <p class="error" id="phone-error">Enter a valid phone number format.</p>
      </div>

      <div class="submit-row">
        <button type="submit">Send message</button>
      </div>
    </form>
  </main>

  <script>
    const form = document.getElementById('support-form');
    const fields = {
      fullName: document.getElementById('fullName'),
      email: document.getElementById('email'),
      phone: document.getElementById('phone')
    };

    const fieldWrappers = {
      fullName: document.querySelector('[data-field="fullName"]'),
      email: document.querySelector('[data-field="email"]'),
      phone: document.querySelector('[data-field="phone"]')
    };

    const touched = {
      fullName: false,
      email: false,
      phone: false
    };

    function isValidPhone(value) {
      if (!value.trim()) return true;
      return /^\+?[0-9()\-\s.]{7,}$/.test(value.trim());
    }

    function validateField(name) {
      const input = fields[name];
      const wrapper = fieldWrappers[name];

      let valid = true;

      if (name === 'fullName') {
        valid = input.value.trim().length > 0;
      } else if (name === 'email') {
        valid = input.validity.valid && input.value.trim().length > 0;
      } else if (name === 'phone') {
        valid = isValidPhone(input.value);
      }

      wrapper.dataset.invalid = (!valid && touched[name]) ? 'true' : 'false';
      return valid;
    }

    function validateAll() {
      return Object.keys(fields).every((name) => {
        touched[name] = true;
        return validateField(name);
      });
    }

    Object.keys(fields).forEach((name) => {
      fields[name].addEventListener('blur', () => {
        touched[name] = true;
        validateField(name);
      });

      fields[name].addEventListener('input', () => {
        if (touched[name]) {
          validateField(name);
        }
      });
    });

    form.addEventListener('submit', (event) => {
      const allValid = validateAll();
      if (!allValid) {
        event.preventDefault();
        return;
      }

      event.preventDefault();
      form.reset();
      Object.keys(touched).forEach((name) => {
        touched[name] = false;
        fieldWrappers[name].dataset.invalid = 'false';
      });
    });
  </script>
</body>
</html>
